                    queue: "q".into(),
                    body: "hi".into(),
                    delay: None,
                    group: GroupId::parse("g"),
                    deduplication: None,
                }),
            ),
        ];
        for (line, expected) in cases {
            assert_eq!(outcome(line), expected, "{line}");
        }
    }

