            (r#"{"Command": "Tick", "Seconds": "30"}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "Tick", "Seconds": 1209601}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "ListQueues", "Prefix": 1}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "SendMessage", "QueueName": "q", "Body": ""}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "SendMessage", "QueueName": "q", "Body": "x", "DelaySeconds": 901}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "SendMessage", "QueueName": "q", "Body": "x", "GroupId": "a b"}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "SendMessage", "QueueName": "q", "Body": "x", "DeduplicationId": ""}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 0}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 11}"#, ErrorCode::InvalidParameterValue),
            (r#"{"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": "r-1", "VisibilityTimeout": 43201}"#, ErrorCode::InvalidParameterValue),
        ];
        for (line, code) in cases {
            assert_eq!(outcome(line), Err(code), "{line}");
        }
    }

