    exec(&mut broker, json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(
        exec(&mut broker, json!({"Command": "SendMessage", "QueueName": "q", "Body": "hello"})),
        json!({"ok": true, "MessageId": "m-1"})
    );
    assert_eq!(
        exec(&mut broker, json!({"Command": "ReceiveMessage", "QueueName": "q"})),
        json!({"ok": true, "Messages": [{
            "MessageId": "m-1",
            "ReceiptHandle": "r-1",
            "Body": "hello",
            "ReceiveCount": 1,
            "SentAt": 0,
            "FirstReceivedAt": 0
        }]})
    );
    assert_eq!(
        exec(&mut broker, json!({"Command": "ReceiveMessage", "QueueName": "q"})),
        json!({"ok": true, "Messages": []})
    );
    let delete = json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"});
    assert_eq!(exec(&mut broker, delete.clone()), json!({"ok": true}));
    assert_eq!(code(&exec(&mut broker, delete)), Some("ReceiptHandleExpired"));
