    exec(&mut broker, json!({"Command": "CreateQueue", "QueueName": "dead"}));
    exec(
        &mut broker,
        json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"DeadLetterQueue": "dead", "MaxReceiveCount": 3}}),
