        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let reply = broker.handle_line(&line);
        serde_json::to_writer(&mut output, &reply)?;
        output.write_all(b"\n")?;
        output.flush()?;
    }
}
